mapper.select:
SELECT tenant_id, parent_session_id, parent_target_kind, parent_target_id, parent_end_user_id, parent_agent_id,
       parent_causation_input_id, parent_run_id, parent_trace_id, parent_span_id, parent_root_input_id,
       parent_caused_by_event_id, parent_causation_identity_ref, parent_requester_kind,parent_requester_end_user_id,parent_requester_system_principal_id,parent_source_session_id,parent_source_message_id,parent_origin_ref,
       delegation_id, operation_key, child_run_id, child_input_id, previous_delegation_id, state, cancel_key,
       revision, snapshot, created_epoch_second, created_nano, updated_epoch_second, updated_nano FROM public.agent_runtime_delegations
WHERE tenant_id=current_setting('app.tenant_id',true)
  AND parent_session_id=#{owner.sessionRef.sessionId}
  AND parent_target_kind=#{owner.target.kind}
  AND parent_target_id=#{owner.target.id}
  AND parent_end_user_id IS NOT DISTINCT FROM NULL#{owner.requireUser.value}
ORDER BY created_epoch_second,created_nano,delegation_id,parent_run_id
LIMIT #{limit}

mapper.update:
UPDATE public.agent_runtime_delegations
SET state=#{row.state},cancel_key=#{row.cancelKey},revision=#{row.revision},
    snapshot=CAST(#{row.snapshot} AS jsonb),
    updated_epoch_second=#{row.updatedEpochSecond},
    updated_nano=#{row.updatedNano}
WHERE tenant_id=current_setting('app.tenant_id',true)
  AND parent_run_id=#{row.parentRunId}
  AND delegation_id=#{row.delegationId}
  AND operation_key=#{row.operationKey}
  AND revision=#{expectedRevision}

mapper.select:
SELECT count(*) FROM public.agent_runtime_delegations
WHERE  AND state IN ('COMPLETED','FAILED','CANCELLED')
  AND delegation_id IN #{id}

SELECT EXISTS(SELECT 1 FROM public.agent_runtime_session_events e
    JOIN public.agent_runtime_dag_works w ON w.tenant_id=e.tenant_id AND w.session_id=e.session_id
        AND w.root_input_id=e.input_id
    JOIN public.agent_runtime_dag_control_runs c ON c.tenant_id=w.tenant_id AND c.session_id=w.session_id AND c.root_input_id=w.root_input_id
    WHERE e.tenant_id=current_setting('app.tenant_id',true) AND e.session_id=#{parent.parentSessionId}
        AND e.target_kind=#{parent.parentTargetKind} AND e.target_id=#{parent.parentTargetId}
        AND e.end_user_id IS NOT DISTINCT FROM #{parent.parentEndUserId,jdbcType=BIGINT} AND e.agent_id=#{parent.parentAgentId}
        AND e.run_id=#{parent.parentRunId} AND e.input_id=#{parent.parentCausationInputId}
        AND e.event_id=('plan-wait:' || #{operation}) AND e.event_type='plan.wait.requested'
        AND c.run_id=#{parent.parentRunId} AND c.agent_id=#{parent.parentAgentId})

SELECT EXISTS(SELECT 1 FROM public.agent_runtime_dag_works w
    JOIN public.agent_runtime_dag_control_runs c USING(tenant_id,session_id,root_input_id)
    WHERE w.tenant_id=current_setting('app.tenant_id',true) AND w.session_id=#{parent.parentSessionId}
      AND w.target_kind=#{parent.parentTargetKind} AND w.target_id=#{parent.parentTargetId}
      AND w.end_user_id IS NOT DISTINCT FROM #{parent.parentEndUserId,jdbcType=BIGINT} AND w.root_input_id=#{work}
      AND w.root_input_id=#{parent.parentCausationInputId}
      AND c.run_id=#{parent.parentRunId} AND c.agent_id=#{parent.parentAgentId}
      AND (w.snapshot::jsonb #>> '{request,controlRun,runId}')=#{parent.parentRunId}
      AND w.status IN ('COMPLETED','CANCELLED'))

SELECT EXISTS(SELECT 1 FROM public.agent_runtime_execution_runs
    WHERE tenant_id=current_setting('app.tenant_id',true) AND session_id=#{parent.parentSessionId}
      AND target_kind=#{parent.parentTargetKind} AND target_id=#{parent.parentTargetId}
      AND end_user_id IS NOT DISTINCT FROM #{parent.parentEndUserId,jdbcType=BIGINT} AND agent_id=#{parent.parentAgentId}
      AND run_id=#{parent.parentRunId} AND input_id=#{parent.parentCausationInputId}
      AND trace_id=#{parent.parentTraceId} AND span_id=#{parent.parentSpanId}
      AND root_input_id=#{parent.parentRootInputId}
      AND caused_by_event_id IS NOT DISTINCT FROM #{parent.parentCausedByEventId,jdbcType=VARCHAR}
      AND identity_ref=#{parent.parentCausationIdentityRef}
      AND requester_kind=#{parent.parentRequesterKind}
      AND requester_end_user_id IS NOT DISTINCT FROM #{parent.parentRequesterEndUserId,jdbcType=BIGINT}
      AND requester_system_principal_id IS NOT DISTINCT FROM #{parent.parentRequesterSystemPrincipalId,jdbcType=VARCHAR}
      AND source_session_id IS NOT DISTINCT FROM #{parent.parentSourceSessionId,jdbcType=VARCHAR}
      AND source_message_id IS NOT DISTINCT FROM #{parent.parentSourceMessageId,jdbcType=VARCHAR}
      AND origin_ref=#{parent.parentOriginRef}
      AND (status IN ('COMPLETED','FAILED','CANCELLED','TERMINATED') OR cancelled))
